mapper.select:
SELECT ri.*
FROM room_info ri
WHERE ri.is_deleted = 0



    AND ri.rent >= #{queryVo.minRent}


    AND ri.rent <= #{queryVo.maxRent}




    AND EXISTS (
    SELECT 1 FROM apartment_info ai
    WHERE ai.id = ri.apartment_id
    AND ai.is_deleted = 0

        AND ai.province_id = #{queryVo.provinceId}


        AND ai.city_id = #{queryVo.cityId}


        AND ai.district_id = #{queryVo.districtId}

    )




    AND EXISTS (
    SELECT 1 FROM room_payment_type rpt
    WHERE rpt.room_id = ri.id
    AND rpt.id = #{queryVo.paymentTypeId}
    AND rpt.is_deleted = 0
    )




    ORDER BY ri.rent ${queryVo.orderType}
